    {"tool": "send_message", "args": {"to": "infra", "content": "Hi! Thanks for checking. I'd like to run the eval today if possible. Can you confirm the test file format? I'll need to understand the label structure to properly parse results. Also, should we verify the test set hasn't drifted from training distribution? That could affect accuracy."}},
    {"tool": "read_file", "args": {"path": "data/test.jsonl"}}
  ],
  "done": false
}
